import pathlib


class KVStoreError(Exception):
    """Base exception for all kvstore errors."""


class RecordError(KVStoreError):
    """Base exception for record encoding and decoding errors."""


class IncompleteRecordError(RecordError):
    """Raised when a record has fewer bytes available than needed."""


class CorruptRecordError(RecordError):
    """Raised when a record has invalid magic, flags, CRC, or UTF-8."""


class CorruptSegmentError(KVStoreError):
    """Raised when a segment contains a corrupt record."""

    def __init__(self, path: pathlib.Path | str, offset: int, reason: str) -> None:
        self.path: pathlib.Path = pathlib.Path(path)
        self.offset: int = offset
        self.reason: str = reason
        super().__init__(
            f"Corrupt segment {self.path.name} at offset {self.offset}: {self.reason}"
        )

import struct
import zlib

from kvstore.errors import CorruptRecordError, IncompleteRecordError

_HEADER_FORMAT = ">4sBHII"
_HEADER_SIZE = 15
_MAGIC = b"KVR1"
_FLAG_VALUE = 0x00
_FLAG_TOMBSTONE = 0x01


def encode_record(key: str, value: str | None) -> bytes:
    if not isinstance(key, str):
        raise TypeError(f"Key must be str, got {type(key).__name__}")
    if value is not None and not isinstance(value, str):
        raise TypeError(f"Value must be str or None, got {type(value).__name__}")

    key_bytes = key.encode("utf-8")
    key_len = len(key_bytes)
    if key_len < 1 or key_len > 65535:
        raise ValueError(f"Key byte length must be in 1..65535, got {key_len}")

    if value is None:
        flags = _FLAG_TOMBSTONE
        value_bytes = b""
        value_len = 0
    else:
        flags = _FLAG_VALUE
        value_bytes = value.encode("utf-8")
        value_len = len(value_bytes)

    payload = key_bytes + value_bytes
    crc = zlib.crc32(payload) & 0xFFFFFFFF
    header = struct.pack(_HEADER_FORMAT, _MAGIC, flags, key_len, value_len, crc)
    return header + payload


def decode_record(buf: bytes, offset: int = 0) -> tuple[str, str | None, int]:
    if offset < 0:
        raise ValueError("Offset cannot be negative")
    if len(buf) - offset < _HEADER_SIZE:
        raise IncompleteRecordError("Buffer has fewer than 15 bytes for header")

    magic, flags, key_len, value_len, expected_crc = struct.unpack_from(
        _HEADER_FORMAT, buf, offset
    )

    if magic != _MAGIC:
        raise CorruptRecordError(f"Bad magic: {magic!r}")
    if flags not in (_FLAG_VALUE, _FLAG_TOMBSTONE):
        raise CorruptRecordError(f"Unknown flags: {flags:#x}")
    if key_len == 0:
        raise CorruptRecordError("key_len cannot be 0")
    if flags == _FLAG_TOMBSTONE and value_len != 0:
        raise CorruptRecordError("Tombstone record cannot have value_len != 0")

    total_size = _HEADER_SIZE + key_len + value_len
    if len(buf) - offset < total_size:
        raise IncompleteRecordError("Buffer has fewer bytes than record requires")

    payload = buf[offset + _HEADER_SIZE : offset + total_size]
    actual_crc = zlib.crc32(payload) & 0xFFFFFFFF
    if actual_crc != expected_crc:
        raise CorruptRecordError(
            f"CRC mismatch: expected {expected_crc:#010x}, got {actual_crc:#010x}"
        )

    try:
        key = payload[:key_len].decode("utf-8")
        if flags == _FLAG_TOMBSTONE:
            value = None
        else:
            value = payload[key_len:].decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CorruptRecordError(f"Invalid UTF-8: {exc}") from exc

    return key, value, total_size

import os
import pathlib
from typing import Iterator

from kvstore.errors import (
    CorruptRecordError,
    CorruptSegmentError,
    IncompleteRecordError,
)
from kvstore.record import decode_record


class Segment:
    def __init__(self, path: pathlib.Path, seg_id: int) -> None:
        self._path = pathlib.Path(path)
        self._seg_id = seg_id
        self._path.parent.mkdir(parents=True, exist_ok=True)
        self._file = open(self._path, "a+b")

    @property
    def path(self) -> pathlib.Path:
        return self._path

    @property
    def seg_id(self) -> int:
        return self._seg_id

    @property
    def size(self) -> int:
        if self._file.closed:
            return self._path.stat().st_size if self._path.exists() else 0
        self._file.flush()
        return os.fstat(self._file.fileno()).st_size

    def append(self, blob: bytes) -> int:
        if self._file.closed:
            raise ValueError("Segment is closed")
        self._file.seek(0, os.SEEK_END)
        offset = self._file.tell()
        self._file.write(blob)
        self._file.flush()
        return offset

    def scan(self) -> Iterator[tuple[str, str | None, int]]:
        if self._file.closed:
            raise ValueError("Segment is closed")
        self._file.flush()
        self._file.seek(0)
        data = self._file.read()
        curr = 0
        data_len = len(data)
        while curr < data_len:
            if data_len - curr < 15:
                break
            try:
                key, value, total_size = decode_record(data, curr)
            except IncompleteRecordError:
                break
            except CorruptRecordError as exc:
                raise CorruptSegmentError(self._path, curr, str(exc)) from exc

            yield key, value, curr
            curr += total_size

    def close(self) -> None:
        if not self._file.closed:
            self._file.close()

import dataclasses


@dataclasses.dataclass(frozen=True)
class Location:
    seg_id: int
    offset: int


class Index:
    def __init__(self) -> None:
        self._entries: dict[str, tuple[Location, bool]] = {}

    def put(self, key: str, loc: Location, *, tombstone: bool) -> None:
        self._entries[key] = (loc, tombstone)

    def get(self, key: str) -> Location | None:
        entry = self._entries.get(key)
        if entry is None or entry[1]:
            return None
        return entry[0]

    def live_keys(self) -> list[str]:
        live = [
            (loc.seg_id, loc.offset, key)
            for key, (loc, is_tombstone) in self._entries.items()
            if not is_tombstone
        ]
        live.sort(key=lambda item: (item[0], item[1]))
        return [item[2] for item in live]

    def tombstone_count(self) -> int:
        return sum(1 for _, (_, is_tombstone) in self._entries.items() if is_tombstone)

    def __len__(self) -> int:
        return sum(
            1 for _, (_, is_tombstone) in self._entries.items() if not is_tombstone
        )

